-- Group chat. Inserted via send_message() only.
-- sender wallet is derived from auth.identities â€” never supplied by the client.
create table if not exists public.messages (
  id         uuid        primary key default gen_random_uuid(),
  group_id   uuid        not null references public.groups(id) on delete cascade,
  sender_id  uuid        not null
                           references auth.users(id) on delete cascade
                           default auth.uid(),
  sender     text        not null check (sender ~ '^0x[0-9a-fA-F]{40}$'),
  body       text        not null check (length(body) between 1 and 2000),
  created_at timestamptz not null default now()
);

-- â”€â”€ loan_requests â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- Off-chain loan request posted to a group. Inserted via post_loan_request().
-- status transitions enforced by update_loan_request_by_borrower() and
-- update_loan_request_status() (service_role only).
create table if not exists public.loan_requests (
  id                 uuid          primary key default gen_random_uuid(),
  group_id           uuid          not null references public.groups(id) on delete cascade,
  borrower_id        uuid          not null
                                     references auth.users(id) on delete cascade
                                     default auth.uid(),
  borrower           text          not null check (borrower ~ '^0x[0-9a-fA-F]{40}$'),
  amount_usdc        numeric(18,6) not null check (amount_usdc > 0),
  duration_days      integer       not null check (duration_days between 1 and 3650),
  note               text          not null default ''
                                     check (length(note) <= 500),
  status             text          not null default 'open'
                                     check (status in
                                       ('open','lender_selected','funded','repaid','cancelled')),
  selected_lender    text          check (selected_lender ~ '^0x[0-9a-fA-F]{40}$'
                                          or selected_lender is null),
  selected_lender_id uuid          references auth.users(id),
  onchain_loan_id    bigint,
  created_at         timestamptz   not null default now(),
  updated_at         timestamptz   not null default now()
);

-- â”€â”€ loan_interests â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- A group member signals interest in lending. Inserted via express_interest().
-- unique(request_id, lender_id) prevents duplicate interest from the same user.
