-- Sole path for a lender expressing interest.
-- lender wallet derived from auth.identities.
-- Enforces unique(request_id, lender_id) â€” duplicate call returns existing row.
-- Borrower cannot also be lender on the same request.
create or replace function public.express_interest(
  p_request_id uuid
)
returns public.loan_interests
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid      uuid;
  v_wallet   text;
  v_group_id uuid;
  v_interest public.loan_interests;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'unauthenticated';
  end if;

  select group_id into v_group_id
  from   public.loan_requests
  where  id = p_request_id;

  if v_group_id is null then
    raise exception 'not_found'
      using hint = 'Loan request not found.';
  end if;

  if not public.is_member_of(v_group_id) then
    raise exception 'forbidden'
      using hint = 'You must be a group member to express lending interest.';
  end if;

  if exists (
    select 1 from public.loan_requests
     where id = p_request_id and borrower_id = v_uid
  ) then
    raise exception 'self_lend'
      using hint = 'Borrower and lender must be different users.';
  end if;

  v_wallet := public._verified_wallet_for_uid(v_uid);
  if v_wallet is null then
    raise exception 'no_identity'
      using hint = 'Web3 identity not found. Please sign in again.';
  end if;

  -- Idempotent: already expressed interest
  select * into v_interest
  from   public.loan_interests
  where  request_id = p_request_id and lender_id = v_uid;

  if found then
    return v_interest;
  end if;

  insert into public.loan_interests (request_id, lender_id, lender)
  values (p_request_id, v_uid, v_wallet)
  returning * into v_interest;

  return v_interest;
end;
$$;

revoke all    on function public.express_interest(uuid) from public, anon;
grant  execute on function public.express_interest(uuid) to authenticated;

-- â”€â”€ withdraw_interest() â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
-- A lender removes their interest record. Server-side complement of the
-- interests_delete_own RLS policy (clients may use either path).
create or replace function public.withdraw_interest(
  p_request_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'unauthenticated';
  end if;

  delete from public.loan_interests
   where request_id = p_request_id
     and lender_id  = v_uid;
end;
$$;

revoke all    on function public.withdraw_interest(uuid) from public, anon;
grant  execute on function public.withdraw_interest(uuid) to authenticated;

